insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('ML', 'ML-P-18', 'Achats de biens 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 229 pour le taux. Le texte consulté ne cite pas explicitement l''article du droit à déduction sur les biens acquis pour les besoins de l''exploitation ; à vérifier avant tout usage en production.', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('ML', 'ML-P-18-IMMO', 'Immobilisations 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 229 pour le taux ; aucun article sur les régularisations de la taxe déduite sur immobilisation n''a été identifié dans le texte consulté.', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('ML', 'ML-P-18-SRV', 'Services extérieurs 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 229 pour le taux. Comme ML-P-18, aucun article du droit à déduction n''a été identifié dans le texte consulté.', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('ML', 'ML-P-5-AGRI', 'Achat de matériel agricole 5 %', '{}'::jsonb, null, 'percent', 5, 'purchase', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 195 IV D, complété par l''art. 2 de l''annexe fiscale à la loi de finances pour l''exercice 2022 — même extension que ML-S-5-AGRI.', 'S', null, 150, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf-2022', null, null, null, null),
  ('ML', 'ML-P-5-HOTEL', 'Hébergement et restauration agréés 5 %', '{}'::jsonb, null, 'percent', 5, 'purchase', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 195 E (nouveau), même annexe fiscale à la loi de finances 2022. Aucun article restreignant la déduction de la taxe sur l''hébergement et la restauration (comme l''art. 383 b du Sénégal) n''a été identifié pour le Mali dans le texte consulté ; cette taxe est donc portée déductible sans restriction, à vérifier avant tout usage en production.', 'S', null, 160, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf-2022', null, null, null, null),
  ('ML', 'ML-P-5-INFO', 'Achat de matériel informatique et solaire 5 %', '{}'::jsonb, null, 'percent', 5, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 195 IV D et art. 229 — même liste de positions tarifaires que ML-S-5-INFO.', 'S', null, 140, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('ML', 'ML-S-18', 'Ventes de biens 18 %', '{}'::jsonb, 'Livraisons de biens au taux normal, TVA au compte 4431', 'percent', 18, 'sale', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 229 — taux de 18 %, confirmé par l''annexe fiscale à la loi de finances 2022 (« le taux retenu par le Mali est 18 % ») ; directive n° 02/2009/CM/UEMOA, art. 29 nouveau — taux normal unique compris entre 15 % et 20 %. Le texte consulté (CGI mis à jour au 02/08/2017) ne date pas l''entrée en vigueur du taux de 18 % lui-même ; 2018-01-01 est la date à partir de laquelle ce pack décrit des livres, le SYSCOHADA révisé, et non celle du taux (voir packs/ci pour la même convention).', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('ML', 'ML-S-18-SRV', 'Prestations de services 18 %', '{}'::jsonb, 'Prestations de services au taux normal, TVA au compte 4432', 'percent', 18, 'sale', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 229 — taux de 18 %. Aucun article fixant le fait générateur propre aux prestations de services (livraison, encaissement, option) n''a été identifié dans le texte de 2017 consulté : ce pack ne porte donc cette taxe en cash_basis nulle part, faute de texte trouvé qui le prescrive ou l''exclue — à vérifier avant tout usage en production.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('ML', 'ML-S-5-AGRI', 'Matériel agricole 5 %', '{}'::jsonb, 'Positions 82.01, 84.24.81.10/90, 84.32.10 à 84.32.80, auparavant exonérées', 'percent', 5, 'sale', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 195 IV D, complété par l''art. 2 de l''annexe fiscale à la loi n° 2021-071 du 23 décembre 2021 (loi de finances pour l''exercice 2022) — extension du taux de 5 % au matériel agricole, applicable à compter de l''exercice 2022.', 'S', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf-2022', null, null, null, null),
  ('ML', 'ML-S-5-HOTEL', 'Hébergement, restauration et circuits touristiques agréés 5 %', '{}'::jsonb, 'Prestations des établissements d''hébergement et de restauration et des organisateurs de circuits touristiques agréés', 'percent', 5, 'sale', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 195 E (nouveau), créé par la même annexe fiscale à la loi de finances pour l''exercice 2022 — taux de 5 % sur les prestations d''hébergement et de restauration des hôtels, restaurants et organismes assimilés agréés, et les prestations des organisateurs de circuits touristiques agréés. L''agrément conditionne le taux : un établissement non agréé facture 18 %.', 'S', null, 50, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf-2022', null, null, null, null),
  ('ML', 'ML-S-5-INFO', 'Matériel informatique et de production d''énergie solaire 5 %', '{}'::jsonb, 'Biens de l''art. 195 IV D : matériel informatique (position 84.71…) et matériels de production d''énergie solaire', 'percent', 5, 'sale', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 195 IV D et art. 229 — liste de positions tarifaires taxées à 5 % ; directive n° 02/2009/CM/UEMOA, art. 29 nouveau — taux réduit de 5 % à 10 % sur une liste communautaire de dix biens ou services au maximum. La date exacte d''entrée en vigueur de ce taux réduit n''a pas été trouvée dans le texte consulté ; 2018-01-01 est la date à partir de laquelle ce pack décrit des livres et non celle du taux (même convention que ML-S-18).', 'S', null, 30, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('ML', 'ML-S-EXO', 'Opération exonérée (art. 195)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2018-01-01', null, 'Code général des impôts, art. 195 — liste des opérations exonérées (exportations et opérations assimilées, biens d''occasion vendus par des particuliers, produits de la pêche, de l''agriculture et de l''élevage non transformés vendus par les producteurs, ventes de l''État et des collectivités hors activité industrielle et commerciale, groupements sans but lucratif, œuvres d''art originales vendues par l''artiste, et une liste de biens par position tarifaire).', 'E', null, 70, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('ML', 'ML-S-EXP', 'Exportation exonérée', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2018-01-01', null, 'Code général des impôts, art. 195 — exonération des exportations. Le texte consulté ne détaille pas, exportation par exportation, la liste que l''article couvre au-delà de cette mention générale ; à vérifier avant tout usage en production.', 'G', null, 60, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

