insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('ML', 'ML-TVA', 'Déclaration de taxe sur la valeur ajoutée', array['month']::declaration_period[], null, date '2018-01-01', null, 'Code général des impôts, Livre de procédures fiscales, art. 110-2 — déclaration mensuelle des redevables au régime du réel normal, due même sans opération, dans les quinze premiers jours de chaque mois pour les opérations du mois précédent. L''art. 110-3 prévoit, pour le régime du réel simplifié, une déclaration annuelle unique au plus tard le 15 mai de l''année suivante : ce pack ne la porte pas, faute de forme de déclaration exprimable par ce schéma pour une échéance à cadence annuelle mais décalée de plusieurs mois (voir le README du pack). Le modèle exact de l''imprimé (« modèle prescrit par l''Administration fiscale ») n''a pas été trouvé ; les cases ci-dessous sont nommées d''après le contenu que la loi impose, non d''après le formulaire.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Code général des impôts, Livre de procédures fiscales, art. 110-2 — la déclaration mensuelle du réel normal est déposée dans les quinze premiers jours du mois qui suit celui des opérations.', 'cgi', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

