values
  ('ML', 'ML-TVA', 'CA18', 'base', 'Opérations taxables au taux normal de 18 %', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229 pour le taux. Le modèle officiel de l''imprimé n''a pas été trouvé : cette case suit le contenu que la loi impose et non la numérotation d''un formulaire.', 'cgi'),
  ('ML', 'ML-TVA', 'CA5', 'base', 'Opérations taxables au taux réduit de 5 %', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 195 IV D et art. 195 E (nouveau) — matériel informatique et solaire, matériel agricole, hébergement, restauration et circuits touristiques agréés, réunis dans une case unique faute de cases distinctes trouvées dans un formulaire officiel.', 'cgi'),
  ('ML', 'ML-TVA', 'EXP', 'base', 'Exportations exonérées', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 195', 'cgi'),
