  numbering_source_key          = 'cgi',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Code général des impôts, art. 447-N — la facture doit mentionner distinctement le montant du précompte exigible et fait foi des mentions qu''elle porte ; aucun article fixant le fait générateur général de la TVA (livraison, encaissement des services) n''a été lu dans le texte de 2017 consulté pour cette fiche. invoice_if_issued reprend le principe le plus répandu dans la zone UEMOA (voir packs/sn et packs/ci) faute d''article malien identifié : à vérifier avant tout usage en production.',
  tax_point_source_key          = 'cgi',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Décret n° 2022-0733/PT-RM du 25 novembre 2022 institue un système sécurisé de facture normalisée (facture sécurisée par un sticker, seul document faisant foi dans les opérations commerciales) ; la loi de finances 2024 annonce « l''introduction » de la facture normalisée et la soumission à la TVA des plateformes de commerce électronique, ce qui indique que le dispositif n''était pas encore en service fin 2023. Aucun arrêté d''application, aucun format technique et aucune date d''obligation effective n''ont été trouvés à la date de ce pack : le profil et la date restent vides.',
  einvoice_source_key           = 'decret-facture-normalisee',
